tool_calls:
mkdir -p /home/eval/recon/out
cat > /tmp/reconcile.awk <<'AWK'
# Convert decimal text to integer cents before doing any arithmetic.
function cents(s,    n,p,frac,sign) {
    gsub(/,/, "", s)
    sign = 1
    if (substr(s,1,1) == "-") { sign = -1; s = substr(s,2) }
    n = split(s,p,".")
    frac = p[2]
    if (length(frac) > 2 && substr(frac,3) !~ /^0*$/) {
        print "Amount is not an exact number of cents: " s > "/dev/stderr"
        exit 1
    }
    frac = substr(frac "00",1,2)
    return sign * ((p[1] + 0) * 100 + (frac + 0))
}
function money(c,    sign) {
    sign = c < 0 ? "-" : ""
    if (c < 0) c = -c
    return sign sprintf("%.0f.%02d", int(c / 100), c % 100)
}
function addid(id) {
    if (!(id in known)) { known[id] = 1; ids[++idcount] = id }
}
function ledger_record(    id) {
    if (++ledger_records == 1) return
    id = field[1]
    ld[id] = field[2]
    la[id] = cents(field[4])
    ledger_total += la[id]
    ledger_rows++
    addid(id)
}
FILENAME == ARGV[1] {
    line = $0
    sub(/\r$/, "", line)
    for (i=1; i<=length(line); i++) {
        ch = substr(line,i,1)
        if (quoted) {
            if (ch == "\"") {
                if (substr(line,i+1,1) == "\"") { value = value "\""; i++ }
                else quoted = 0
            } else value = value ch
        } else if (ch == "\"") quoted = 1
        else if (ch == ",") { field[++nf] = value; value = "" }
        else value = value ch
    }
    if (quoted) { value = value "\n"; next }
    field[++nf] = value
    ledger_record()
    for (j in field) delete field[j]
    nf = 0; value = ""
    next
}
FNR == 1 { next }
{
    line = $0
    sub(/\r$/, "", line)
    split(line,b,"\t")
    id = b[1]
    gsub(/^ +| +$/, "", id)
    id = toupper(id)
    split(b[2],d,"/")
    date = d[3] "-" d[2] "-" d[1]
    amount = cents(b[4])
    key = id SUBSEP date SUBSEP amount
    if (key in seen) { duplicates++; next }
    seen[key] = 1
    bd[id] = date; ba[id] = amount
    bank_rows++; bank_total += amount
    addid(id)
}
END {
    for (i=2; i<=idcount; i++) {
        id = ids[i]; j = i-1
        while (j >= 1 && ids[j] > id) { ids[j+1] = ids[j]; j-- }
        ids[j+1] = id
    }
    for (i=1; i<=idcount; i++) {
        id = ids[i]
        if (!(id in la)) { missing_ledger++; ml = ml "  " id "\n" }
        else if (!(id in ba)) { missing_bank++; mb = mb "  " id "\n" }
        else {
            if (la[id] == ba[id] && ld[id] == bd[id]) matched++
            if (la[id] != ba[id]) {
                amount_mismatch++
                am = am "  " id " ledger=" money(la[id]) " bank=" money(ba[id]) "\n"
            }
            if (ld[id] != bd[id]) {
                date_mismatch++
                dm = dm "  " id " ledger=" ld[id] " bank=" bd[id] "\n"
            }
        }
    }
    printf "ledger_rows: %d\nbank_rows: %d\nduplicate_bank_rows: %d\n", ledger_rows,bank_rows,duplicates
    printf "ledger_total: %s\nbank_total: %s\nmatched: %d\n", money(ledger_total),money(bank_total),matched
    printf "amount_mismatch: %d\n%s", amount_mismatch,am
    printf "date_mismatch: %d\n%s", date_mismatch,dm
    printf "missing_in_bank: %d\n%s", missing_bank,mb
    printf "missing_in_ledger: %d\n%s", missing_ledger,ml
}
AWK
LC_ALL=C awk -f /tmp/reconcile.awk /home/eval/recon/ledger.csv /home/eval/recon/bank.tsv > /home/eval/recon/out/reconciliation.txt
cat /home/eval/recon/out/reconciliation.txt

